#include <stdio.h>
#include <string.h>

void computeCRC(char data[], char divisor[])
{
    char dividend[100], temp[100];
    int dataLen, divLen, i, j;

    strcpy(dividend, data);

    dataLen = strlen(data);
    divLen = strlen(divisor);

    /* Append zeros */
    for(i = 0; i < divLen - 1; i++)
        dividend[dataLen + i] = '0';

    dividend[dataLen + divLen - 1] = '\0';

    strcpy(temp, dividend);

    /* Modulo-2 division */
    for(i = 0; i <= strlen(temp) - divLen; i++)
    {
        if(temp[i] == '1')
        {
            for(j = 0; j < divLen; j++)
            {
                temp[i + j] =
                    (temp[i + j] == divisor[j]) ? '0' : '1';
            }
        }
    }

    printf("\nDataword      : %s", data);
    printf("\nGenerator     : %s", divisor);

    printf("\nCRC Remainder : ");
    for(i = strlen(temp) - (divLen - 1); i < strlen(temp); i++)
        printf("%c", temp[i]);

    printf("\nCodeword      : %s", data);

    for(i = strlen(temp) - (divLen - 1); i < strlen(temp); i++)
        printf("%c", temp[i]);

    printf("\n");
}

int main()
{
    char data[100];
    int choice;

    printf("Enter binary data: ");
    scanf("%s", data);

    printf("\nChoose CRC Polynomial");
    printf("\n1. CRC-12");
    printf("\n2. CRC-16");
    printf("\n3. CRC-CCITT");
    printf("\nEnter choice: ");
    scanf("%d", &choice);

    switch(choice)
    {
        case 1:
            computeCRC(data, "1100000001111");
            break;

        case 2:
            computeCRC(data, "11000000000000101");
            break;

        case 3:
            computeCRC(data, "10001000000100001");
            break;

        default:
            printf("Invalid choice!\n");
    }

    return 0;
}

#include <stdio.h>

int main() {
    int totalFrames, windowSize;
    int base = 0, i, end, lostFrame;

    printf("Enter the total number of frames: ");
    scanf("%d", &totalFrames);

    printf("Enter the window size: ");
    scanf("%d", &windowSize);

    while (base < totalFrames) {
        end = (base + windowSize < totalFrames) ? (base + windowSize) : totalFrames;

        printf("\nSending Frames: ");
        for (i = base; i < end; i++) {
            printf("%d ", i);
        }

        printf("\nEnter the lost frame number (-1 for no loss): ");
        scanf("%d", &lostFrame);

        if (lostFrame == -1 || lostFrame < base || lostFrame >= end) {
            printf("All frames acknowledged.\n");
            base = end;
        } else {
            printf("Frame %d lost.\n", lostFrame);
            printf("Go-Back-N: Retransmitting from Frame %d.\n", lostFrame);
            base = lostFrame;
        }
    }

    printf("\nAll frames transmitted successfully.\n");

    return 0;
}

#include <stdio.h>

#define MAX 10
#define INF 9999

int main() {
    int graph[MAX][MAX], distance[MAX], visited[MAX];
    int n, source, i, j, min, next;

    printf("Enter the number of vertices: ");
    scanf("%d", &n);

    printf("Enter the adjacency matrix:\n");
    for(i = 0; i < n; i++) {
        for(j = 0; j < n; j++) {
            scanf("%d", &graph[i][j]);

            // Replace 0 with INF (except diagonal)
            if(graph[i][j] == 0 && i != j)
                graph[i][j] = INF;
        }
    }

    printf("Enter the source vertex (0 to %d): ", n - 1);
    scanf("%d", &source);

    // Initialize distances and visited array
    for(i = 0; i < n; i++) {
        distance[i] = graph[source][i];
        visited[i] = 0;
    }

    distance[source] = 0;
    visited[source] = 1;

    // Dijkstra's Algorithm
    for(i = 1; i < n; i++) {
        min = INF;

        for(j = 0; j < n; j++) {
            if(!visited[j] && distance[j] < min) {
                min = distance[j];
                next = j;
            }
        }

        visited[next] = 1;

        for(j = 0; j < n; j++) {
            if(!visited[j] && (min + graph[next][j] < distance[j])) {
                distance[j] = min + graph[next][j];
            }
        }
    }

    // Display shortest distances
    printf("\nShortest distances from vertex %d:\n", source);
    for(i = 0; i < n; i++) {
        printf("To vertex %d = %d\n", i, distance[i]);
    }

    return 0;
}
